import React, { useEffect, useState, useContext } from 'react';
import { Container, ListGroup, ListGroupItem, Button, Spinner } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import { DataContext } from '../../../context/DataContext';

const BASE_URL = 'http://localhost:8080'; // 실제 API URL을 넣으세요

const ChatList = ({ toggleChat }) => {
    const [stompClient, setStompClient] = useState(null);
    const [chatsData, setChatsData] = useState([]);
    const { data } = useContext(DataContext);
    const { loginUser } = data || {}; // Ensure data is always an object
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const id = loginUser?.email;
        if (id) {
            fetchChats(id);
        }

        const socket = new SockJS(`${BASE_URL}/ws`);
        const client = new Client({
            webSocketFactory: () => socket,
            debug: function (str) {
                console.log(str);
            },
            reconnectDelay: 5000,
        });

        client.onConnect = () => {
            setStompClient(client);
            client.subscribe('/topic/chats', (msg) => {
                if (msg.body) {
                    setChatsData(JSON.parse(msg.body));
                }
            });
        };

        client.activate();

        return () => {
            if (client) {
                client.deactivate();
            }
        };
    }, [loginUser]);

    const fetchChats = (id) => {
        fetch(`${BASE_URL}/api/chats?userId=${id}`)
            .then((response) => response.json())
            .then((data) => {
                setChatsData(data);
                setLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching chat data:', error);
                setLoading(false);
            });
    };

    const renderChatListItem = (item) => {
        const otherUserId = item.from_id === loginUser?.email ? item.to_id : item.from_id;

        return (
            <ListGroupItem key={item.id} className="d-flex justify-content-between align-items-center">
                <div>
                    <strong>{otherUserId}</strong>
                    <p>{item.last_message}</p>
                    <small>{new Date(item.time).toLocaleString()}</small>
                </div>
                <Button color="primary" onClick={() => toggleChat(item.id, otherUserId)}>
                    채팅하기
                </Button>
            </ListGroupItem>
        );
    };

    return (
        <Container>
            {loading ? (
                <Spinner color="primary" />
            ) : chatsData.length > 0 ? (
                <ListGroup>{chatsData.map((item) => renderChatListItem(item))}</ListGroup>
            ) : (
                <div className="text-center">
                    <p>채팅 내역이 없습니다</p>
                    <p>id : {loginUser?.email}</p>
                </div>
            )}
        </Container>
    );
};

export default ChatList;
